export interface StyleValue {
    sid: Sid
    xmlName: string
    type: P_TYPE
    defaultValue: PropertyValue
}

function styleDef(sid: Sid, type: P_TYPE, defaultValue: PropertyValue): StyleValue {
    return { sid, xmlName: Sid[sid], type, defaultValue }
}

